// ✅ Validação e preparação do payload
const body = $input.first().json.body || $input.first().json;

const text = body.text || body.message || body.content;
const senderEmail = body.sender_email || body.email || 'destinatario@exemplo.com';
const senderName = body.sender_name || body.name || 'Usuário';

if (!text || typeof text !== 'string' || text.trim().length === 0) {
  throw new Error('Campo "text" obrigatório e não pode estar vazio.');
}

if (text.trim().length < 3) {
  throw new Error('Texto muito curto para análise (mínimo 3 caracteres).');
}

if (text.trim().length > 5000) {
  throw new Error('Texto excede o limite de 5000 caracteres.');
}

return [{
  json: {
    text: text.trim(),
    sender_email: senderEmail,
    sender_name: senderName,
    char_count: text.trim().length,
    received_at: new Date().toISOString()
  }
}];

// 🔬 Parsear e enriquecer resultado da OpenAI
const openaiResponse = $input.first().json;
const previousData = $('🔍 Validar e Preparar Payload').first().json;

// Extrair o conteúdo da resposta
let rawContent = '';
try {
  rawContent = openaiResponse.choices[0].message.content;
} catch (e) {
  throw new Error('Resposta inválida da API OpenAI: ' + JSON.stringify(openaiResponse));
}

// Remover possíveis backticks de markdown
rawContent = rawContent.replace(/```json/g, '').replace(/```/g, '').trim();

// Parsear JSON
let analysis;
try {
  analysis = JSON.parse(rawContent);
} catch (e) {
  throw new Error('OpenAI não retornou JSON válido: ' + rawContent);
}

// Validar campos obrigatórios
const validSentiments = ['POSITIVO', 'NEGATIVO', 'NEUTRO'];
if (!validSentiments.includes(analysis.sentiment)) {
  analysis.sentiment = 'NEUTRO'; // fallback seguro
}

// Calcular nível de confiança
const confidence = analysis.confidence || 0.5;
let confidenceLabel = 'Baixa';
if (confidence >= 0.85) confidenceLabel = 'Alta';
else if (confidence >= 0.65) confidenceLabel = 'Média';

// Emojis por sentimento
const emojiMap = { 'POSITIVO': '😊', 'NEGATIVO': '😟', 'NEUTRO': '😐' };
const colorMap = { 'POSITIVO': '#22c55e', 'NEGATIVO': '#ef4444', 'NEUTRO': '#f59e0b' };

// Tokens usados
const tokens_used = openaiResponse.usage?.total_tokens || 0;

return [{
  json: {
    // Dados originais
    original_text: previousData.text,
    sender_email: previousData.sender_email,
    sender_name: previousData.sender_name,
    received_at: previousData.received_at,
    char_count: previousData.char_count,

    // Resultado da análise
    sentiment: analysis.sentiment,
    confidence: confidence,
    confidence_label: confidenceLabel,
    dominant_emotion: analysis.dominant_emotion || 'neutro',
    brief_reason: analysis.brief_reason || 'Análise concluída',
    keywords: analysis.keywords || [],

    // Metadados
    emoji: emojiMap[analysis.sentiment],
    color: colorMap[analysis.sentiment],
    tokens_used: tokens_used,
    analyzed_at: new Date().toISOString()
  }
}];

